function questionChildren(q){return (S.data.QUESTIONS||[]).filter(x=>String(codeOf(x.Question_parente_Code)||"")===String(q.id))}
function externalRulesUsingQuestion(q){return (S.data.REGLES_CONDITION||[]).filter(r=>String(codeOf(r.Question_source_Code)||"")===String(q.id)).filter(r=>{const c=conditionByRef(r.Condition_Code);if(!c)return true;const own=[conditionByRef(q.Condition_affichage_Code),conditionByRef(q.Condition_obligation_Code)].filter(Boolean).map(x=>String(x.id));const choiceConds=choicesFor(q).map(x=>conditionByRef(x.Condition_Code)).filter(Boolean).map(x=>String(x.id));return ![...own,...choiceConds].includes(String(c.id))})}
function ownedConditionsForQuestion(q){const out=[conditionByRef(q.Condition_affichage_Code),conditionByRef(q.Condition_obligation_Code)];for(const c of choicesFor(q))out.push(conditionByRef(c.Condition_Code));return [...new Map(out.filter(Boolean).map(c=>[String(c.id),c])).values()]}
async function deleteElement(type,row){if(type==="page"){const pc=codeOf(row.Page_Code),hasSections=(S.data.SECTIONS||[]).some(s=>ref(s.Page_Code,S.data.PAGES,"Page_Code")===pc),hasQuestions=(S.data.QUESTIONS||[]).some(q=>ref(q.Page_Code,S.data.PAGES,"Page_Code")===pc);if(hasSections||hasQuestions)throw new Error("Cette page contient encore des sections ou des questions. Supprimez-les d’abord.")}
 if(type==="section"){const sc=codeOf(row.Section_Code),hasQuestions=(S.data.QUESTIONS||[]).some(q=>ref(q.Section_Code,S.data.SECTIONS,"Section_Code")===sc);if(hasQuestions)throw new Error("Cette section contient encore des questions. Supprimez-les d’abord.")}
 if(type==="question"){const children=questionChildren(row),nonMatrixChildren=children.filter(x=>!isMatrixLine(x));if(nonMatrixChildren.length)throw new Error("Cette question possède une ou plusieurs questions complémentaires. Supprimez-les d’abord.");const ext=externalRulesUsingQuestion(row);if(ext.length)throw new Error("Cette question est utilisée dans une condition d’un autre élément. Retirez d’abord cette dépendance.")}
 const name=label(row,type);if(!confirm(`Supprimer définitivement « ${name} » ?`))return;const actions=[];
 if(type==="question"){for(const child of questionChildren(row).filter(isMatrixLine))actions.push(["RemoveRecord","QUESTIONS",Number(child.id)]);const conds=ownedConditionsForQuestion(row);for(const c of conds)for(const r of rulesForCondition(c))actions.push(["RemoveRecord","REGLES_CONDITION",Number(r.id)]);for(const f of choiceFiltersFor(row))actions.push(["RemoveRecord","FILTRES_CHOIX",Number(f.id)]);for(const c of choicesFor(row))actions.push(["RemoveRecord","CHOIX_QUESTIONS",Number(c.id)]);for(const c of matrixColumns(row))actions.push(["RemoveRecord","COLONNES_MATRICE",Number(c.id)]);for(const c of conds)actions.push(["RemoveRecord","CONDITIONS",Number(c.id)])}
 actions.push(["RemoveRecord",tableFor(type),Number(row.id)]);await grist.docApi.applyUserActions(actions);S.selected=null;await reload();$("#properties").innerHTML='<div class="empty-state">Élément supprimé.</div>';$("#canvas").innerHTML='<div class="empty-state">Sélectionnez un élément.</div>';status("Élément supprimé.")}
const tableFor=t=>({page:"PAGES",section:"SECTIONS",question:"QUESTIONS"}[t]);
async function update(t,id,ch){try{await grist.docApi.applyUserActions([["UpdateRecord",tableFor(t),Number(id),ch]]);status("Modification enregistrée.");await reload();const nr=rows(t).find(x=>String(x.id)===String(id));if(nr){S.selected={type:t,row:nr};renderTree();renderEditor()}}catch(e){status(e?.message||e,true)}}
const unique=p=>`${p}_${Date.now().toString(36).toUpperCase()}_${Math.random().toString(36).slice(2,6).toUpperCase()}`;
const versionRow=()=>S.data.VERSIONS_QUESTIONNAIRES.find(v=>codeOf(v.Version_Code)===S.version);
const maxOrder=a=>Math.max(0,...a.map(r=>Number(r.Ordre)||0))+1;
async function add(t){try{const {pages,sections,questions}=current(),v=versionRow();if(!v)throw new Error("Version introuvable.");let table,values;if(t==="page"){table="PAGES";const sm=S.data.PAGES[0]||{};values={Page_Code:unique("PAGE"),Version_Code:v.id,Ordre:maxOrder(pages)};const k=field(sm,["Titre","Nom","Libelle"]);if(k)values[k]="Nouvelle page";if(field(sm,["Active"]))values.Active=true}if(t==="section"){const p=S.selected?.type==="page"?S.selected.row:S.selected?.type==="section"?S.data.PAGES.find(x=>String(x.id)===String(S.selected.row.Page_Code)):S.selected?.type==="question"?S.data.PAGES.find(x=>String(x.id)===String(codeOf(S.selected.row.Page_Code)||codeOf(S.data.SECTIONS.find(s=>String(s.id)===String(codeOf(S.selected.row.Section_Code)))?.Page_Code))):null;if(!p)throw new Error("Sélectionnez d’abord une page, une section ou une question de cette page.");table="SECTIONS";const sm=S.data.SECTIONS[0]||{};values={Section_Code:unique("SEC"),Version_Code:v.id,Page_Code:p.id,Ordre:maxOrder(sections.filter(s=>String(s.Page_Code)===String(p.id)))};const k=field(sm,["Titre","Nom","Libelle"]);if(k)values[k]="Nouvelle section";if(field(sm,["Active"]))values.Active=true}if(t==="fiche"){
 const sec=S.selected?.type==="section"?S.selected.row:null;
 if(!sec)throw new Error("Sélectionnez d’abord la section.");
 const ficheSm=S.data.TYPES_FICHES[0]||{},ficheCode=unique("FICHE");
 const ficheValues={TypeFiche_Code:ficheCode,Version_Code:v.id,Ordre:maxOrder((S.data.TYPES_FICHES||[]).filter(f=>!isSubFiche(f)))};
 const sing=field(ficheSm,["Libelle_singulier","Libellé_singulier","Libelle","Nom"]),plur=field(ficheSm,["Libelle_pluriel","Libellé_pluriel"]);
 if(sing)ficheValues[sing]="Nouvelle fiche";
 if(plur)ficheValues[plur]="Nouvelles fiches";
 if(field(ficheSm,["Minimum"]))ficheValues.Minimum=0;
 if(field(ficheSm,["Autoriser_ajout"]))ficheValues.Autoriser_ajout=true;
 if(field(ficheSm,["Autoriser_suppression"]))ficheValues.Autoriser_suppression=true;
 if(field(ficheSm,["Active"]))ficheValues.Active=true;
 await grist.docApi.applyUserActions([["AddRecord","TYPES_FICHES",null,ficheValues]]);
 await reload();
 const created=(S.data.TYPES_FICHES||[]).find(f=>codeOf(f.TypeFiche_Code)===ficheCode);
 if(!created)throw new Error("Fiche créée mais introuvable après relecture.");
 const qSm=S.data.QUESTIONS[0]||{},page=S.data.PAGES.find(x=>String(x.id)===String(sec.Page_Code));
 const qValues={Question_Code:unique("Q"),Version_Code:v.id,Section_Code:sec.id,TypeFiche_Code:created.id,Ordre:maxOrder(questions.filter(q=>String(q.Section_Code)===String(sec.id)))};
 if(page&&field(qSm,["Page_Code"]))qValues.Page_Code=page.id;
 const qLabel=field(qSm,["Libelle","Libellé","Question","Titre"]);if(qLabel)qValues[qLabel]="Nouvelle question";
 if(field(qSm,["Active"]))qValues.Active=true;
 if(field(qSm,["Mode_obligation"]))qValues.Mode_obligation="Facultative";
 const qType=field(qSm,["Type_question","Type_reponse","Type","Format"]);if(qType)qValues[qType]="Texte";
 await grist.docApi.applyUserActions([["AddRecord","QUESTIONS",null,qValues]]);
 await reload();
 const fresh=(S.data.TYPES_FICHES||[]).find(f=>codeOf(f.TypeFiche_Code)===ficheCode);
 if(fresh){S.selected={type:"fiche",row:fresh};renderTree();renderEditor();}
 status("Fiche ajoutée.");
 return;
}
if(t==="question"){const s=S.selected?.type==="section"?S.selected.row:S.selected?.type==="question"?S.data.SECTIONS.find(x=>String(x.id)===String(S.selected.row.Section_Code)):null;if(!s)throw new Error("Sélectionnez d’abord la section.");const p=S.data.PAGES.find(x=>String(x.id)===String(s.Page_Code));table="QUESTIONS";const sm=S.data.QUESTIONS[0]||{};values={Question_Code:unique("Q"),Version_Code:v.id,Section_Code:s.id,Ordre:maxOrder(questions.filter(q=>String(q.Section_Code)===String(s.id)))};if(p&&field(sm,["Page_Code"]))values.Page_Code=p.id;const k=field(sm,["Libelle","Libellé","Question","Titre"]);if(k)values[k]="Nouvelle question";if(field(sm,["Active"]))values.Active=true;if(field(sm,["Mode_obligation"]))values.Mode_obligation="Facultative";const tk=field(sm,["Type_question","Type_reponse","Type","Format"]);if(tk)values[tk]="Texte"}await grist.docApi.applyUserActions([["AddRecord",table,null,values]]);status("Élément ajouté.");await reload();if(t==="question"){const created=(S.data.QUESTIONS||[]).find(q=>String(codeOf(q.Question_Code))===String(values.Question_Code));if(!created)throw new Error("Question créée mais introuvable après relecture.");S.selected={type:"question",row:created};renderTree();renderEditor();requestAnimationFrame(()=>{document.querySelector(`.tree-item[data-type="question"][data-id="${created.id}"]`)?.scrollIntoView({block:"nearest",behavior:"smooth"})})}}catch(e){status(e?.message||e,true)}}
function status(m,err=false,persistent=false){const node=$("#status");node.innerHTML=`<div class="${err?"status-error":"status-ok"}">${esc(m)}</div>`;if(!err&&!persistent)setTimeout(()=>{if(node.textContent===m)node.innerHTML=""},3500)}
function bind(){$("#questionnaire-select").onchange=e=>{S.questionnaire=e.target.value;S.version=null;S.selected=null;renderSelectors()};$("#version-select").onchange=e=>{S.version=e.target.value;S.selected=null;renderTree()};$("#add-page").onclick=()=>add("page");$("#add-section").onclick=()=>add("section");$("#add-question").onclick=()=>add("question")}
async function start(){try{grist.ready({requiredAccess:"full"});await reload();bind()}catch(e){status(`Impossible de charger le Concepteur : ${e?.message||e}`,true)}}start();
